import json
from typing import Any, Dict

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _num(v):
    try:
        return float(str(v).strip() or 0)
    except Exception:
        return 0.0

async def main(args):
    p = args.params
    # 兼容：单品旧结构（顶层标量）退化为一元素；批量优先取 offers
    offers = [o for o in _load(p.get('offers')) if isinstance(o, dict)]
    if not offers and str(p.get('offer_id') or ''):
        offers = [{'offer_seq': 1, 'offer_id': str(p.get('offer_id') or ''),
                   'offer_name': str(p.get('offer_name') or ''),
                   'order_count': str(p.get('order_count') or ''),
                   'order_trend': str(p.get('order_trend') or ''),
                   'error_count': str(p.get('error_count') or ''),
                   'error_trend': str(p.get('error_trend') or ''),
                   'fee_error_rate': str(p.get('fee_error_rate') or ''),
                   'fee_trend': str(p.get('fee_trend') or ''),
                   'alarm_list': p.get('alarm_list') or []}]
    norm = []
    err_total = 0.0
    any_abnormal = False
    first = None
    for i, o in enumerate(offers, start=1):
        seq = o.get('offer_seq') if o.get('offer_seq') not in (None, '') else i
        ec = _num(o.get('error_count'))
        fr = _num(o.get('fee_error_rate'))
        abnormal = (ec != 0) or (fr > 0.1)
        norm.append({'offer_seq': seq,
                     'offer_id': str(o.get('offer_id') or ''),
                     'offer_name': str(o.get('offer_name') or ''),
                     'order_count': str(o.get('order_count') or ''),
                     'order_trend': str(o.get('order_trend') or ''),
                     'error_count': str(o.get('error_count') or ''),
                     'error_trend': str(o.get('error_trend') or ''),
                     'fee_error_rate': str(o.get('fee_error_rate') or ''),
                     'fee_trend': str(o.get('fee_trend') or ''),
                     'alarm_list': o.get('alarm_list') or []})
        err_total += ec
        if abnormal:
            any_abnormal = True
            if first is None:
                first = norm[-1]
    if first is None and norm:
        first = norm[0]
    f = first or {}
    def _j(v):
        return v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)
    def _pct(v):
        # 计费差错率小数（如 0.0020）转百分比文本，供自然语言简报展示
        try:
            return '%.2f%%' % (_num(v) * 100)
        except Exception:
            return ''
    def _alarms(v):
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except Exception:
                v = [v] if v.strip() else []
        if isinstance(v, list) and v:
            texts = []
            for x in v:
                if isinstance(x, dict):
                    t = x.get('content') or x.get('alarm_content') or x.get('message') or ''
                    lv = x.get('alarm_level') or ''
                    texts.append(('%s（%s）' % (t, lv)) if (t and lv) else (str(t) if t else str(x)))
                else:
                    texts.append(str(x))
            return '、'.join(texts)
        return '无'
    lines = []
    for o in norm:
        nm = str(o.get('offer_name') or '') or '未登记'
        lines.append('- %s：订单量 %s（%s），异常量 %s（%s），计费差错率 %s（%s），告警：%s'
                     % (nm, str(o.get('order_count') or ''), str(o.get('order_trend') or ''),
                        str(o.get('error_count') or ''), str(o.get('error_trend') or ''),
                        _pct(o.get('fee_error_rate')), str(o.get('fee_trend') or ''),
                        _alarms(o.get('alarm_list'))))
    ret: Output = {
        'error_count': ('%g' % err_total) if err_total else '0',
        'any_abnormal': 'true' if any_abnormal else 'false',
        'first_offer_id': str(f.get('offer_id') or ''),
        'first_offer_name': str(f.get('offer_name') or ''),
        'first_order_count': str(f.get('order_count') or ''),
        'first_order_trend': str(f.get('order_trend') or ''),
        'first_error_count': str(f.get('error_count') or ''),
        'first_error_trend': str(f.get('error_trend') or ''),
        'first_fee_error_rate': str(f.get('fee_error_rate') or ''),
        'first_fee_trend': str(f.get('fee_trend') or ''),
        'first_alarm_list': _j(f.get('alarm_list') or []),
        'offers': json.dumps(norm, ensure_ascii=False),
        'monitor_lines': '\n'.join(lines)
    }
    return ret

