import json, urllib.request
from typing import Any, Dict

WO_URL = 'http://10.86.13.201:31281/api/v1/appstore/ops/work-orders'

def _fetch(offer_id):
    body = json.dumps({'offer_id': offer_id}).encode('utf-8')
    req = urllib.request.Request(WO_URL, data=body, method='POST',
                                 headers={'Content-Type': 'application/json'})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.loads(resp.read().decode('utf-8'))

async def main(args):
    p = args.params
    offer_id = str(p.get('offer_id') or '')
    try:
        info = _fetch(offer_id)
    except Exception:
        info = None
    wo_id = str((info or {}).get('work_order_id') or '')
    if not info or not wo_id:
        ret: Output = {
            'backend_pending': '1',
            'work_order_id': '',
            'note': '建工单服务(create_work_order)端点暂不可达，工单未建立，稍后回检重试',
        }
    else:
        ret: Output = {
            'backend_pending': '0',
            'work_order_id': wo_id,
            'note': str(info.get('message') or '工单已建立'),
        }
    return ret

